    let (mut buy1, mut sell1) = (-prices[0], 0);
    let (mut buy2, mut sell2) = (-prices[0], 0);

    for &price in &prices {
      buy1 = buy1.max(-price);
      sell1 = sell1.max(buy1 + price);
